    $script:Workflow    = Join-Path $PSScriptRoot '.github/workflows/artifact-cleanup-script.yml'
    $script:FixtureDir  = Join-Path $PSScriptRoot 'fixtures'

    # Helper to build artifacts tersely in unit tests.
