    $retain = @($items | Where-Object { $_.Reasons.Count -eq 0 })

    $project = {
        param($it)
        [pscustomobject]@{
            Name          = $it.Name
            Size          = $it.Size
            Created       = $it.Created
            WorkflowRunId = $it.WorkflowRunId
            Reasons       = @($it.Reasons)
        }
    }

    $reclaimed = ($delete | Measure-Object -Property Size -Sum).Sum
    if ($null -eq $reclaimed) { $reclaimed = 0 }
    $retainedSize = ($retain | Measure-Object -Property Size -Sum).Sum
    if ($null -eq $retainedSize) { $retainedSize = 0 }

